import os,re,json
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))

import numpy as np, json
from scipy import ndimage
def f(g):
    g=np.array(g); h,w=g.shape; bg=g[0,0]
    mask=(g!=bg)&(g!=7)
    lab,n=ndimage.label(mask, structure=np.ones((3,3)))
    obj=None;best=0
    for k in range(1,n+1):
        rs,cs=np.where(lab==k)
        s=int((lab==k).sum())
        if s>=2 and s>best: best=s; obj=k
    rs,cs=np.where(lab==obj)
    P=g[rs.min():rs.max()+1, cs.min():cs.max()+1]
    hh,ww=P.shape
    out=g.copy()
    for r in range(h):
        for c in range(w):
            if g[r,c]==7:
                R=r-hh; C=c-ww
                if 0<=R and 0<=C and R+hh<=h and C+ww<=w:
                    out[R:R+hh,C:C+ww]=P
    return out.tolist()
print(f(G['Demo pair 1 input'])==G['Demo pair 1 output'])
